def read_csv(path):
    with path.open(newline="") as fh:
        return list(csv.DictReader(fh))


def as_float(value):
    if value == "" or value is None:
        return 0.0
    return float(value)


def safe_value(value):
    if abs(value) <= 5e-9:
        return 0.0
    if value < 0.0 and value > -1e-7:
        return 0.0
    return value


def fmt(value):
    return f"{safe_value(value):.8f}"


